import com.craftmarket.mapper.BoothMapper;
import com.craftmarket.mapper.MarketEventMapper;
import com.craftmarket.mapper.VendorMapper;
import com.craftmarket.service.BoothService;
import com.craftmarket.service.MarketEventService;
import com.craftmarket.service.VendorService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Slf4j
public class BoothServiceImpl extends ServiceImpl<BoothMapper, Booth> implements BoothService {

    @Autowired
    private VendorService vendorService;

    @Autowired
    private MarketEventMapper marketEventMapper;

    @Autowired
    private VendorMapper vendorMapper;

    @Override
    @Transactional
    public boolean batchSaveBooths(List<Booth> booths) {
        if (booths == null || booths.isEmpty()) {
            throw new IllegalArgumentException("摊位列表不能为空");
        }

        // 验证活动是否存在
        Long eventId = booths.get(0).getMarketEventId();
        if (marketEventMapper.selectById(eventId) == null) {
            throw new IllegalArgumentException("活动不存在");
        }

        return saveBatch(booths);
    }

    @Override
    public Booth getBoothById(Long id) {
        return getById(id);
    }

    @Override
    public Page<Booth> getBoothsPage(Integer current, Integer size, String area, Booth.BoothStatus status) {
        Page<Booth> page = new Page<>(current, size);
        LambdaQueryWrapper<Booth> queryWrapper = new LambdaQueryWrapper<>();

        if (area != null && !area.trim().isEmpty()) {
            queryWrapper.like(Booth::getArea, area);
        }

        if (status != null) {
            queryWrapper.eq(Booth::getStatus, status);
        }

        queryWrapper.orderByDesc(Booth::getCreateTime);
        return page(page, queryWrapper);
    }

    @Override
    public Page<Booth> getAvailableBoothsByArea(String area, Page<Booth> page) {
        return lambdaQuery()
                .eq(Booth::getStatus, BoothStatus.AVAILABLE)
                .like(area != null && !area.trim().isEmpty(), Booth::getArea, area)
                .orderByDesc(Booth::getCreateTime)
                .page(page);
    }

    @Override
    @Transactional
    public boolean assignBoothToVendor(Long boothId, Long vendorId, Long eventId) {
        // 验证摊位是否存在
        Booth booth = getById(boothId);
        if (booth == null) {
            throw new IllegalArgumentException("摊位不存在");
        }

        // 验证摊主是否存在
        Vendor vendor = vendorService.getVendorById(vendorId);
        if (vendor == null) {
            throw new IllegalArgumentException("摊主不存在");
        }

        // 验证摊位是否可用
        if (!BoothStatus.AVAILABLE.equals(booth.getStatus())) {
            throw new IllegalStateException("该摊位不可分配");
        }

        // 验证摊位是否属于该活动
        if (!eventId.equals(booth.getMarketEventId())) {
            throw new IllegalArgumentException("摊位不属于该活动");
        }

        // 更新摊位状态
        booth.setStatus(BoothStatus.ASSIGNED);
        booth.setVendorId(vendorId);
        booth.setUpdateTime(LocalDateTime.now());
        boolean updateResult = updateById(booth);

        if (updateResult) {
            // 可以在这里添加创建订单的逻辑
            // createOrder(vendorId, eventId, boothId, booth.getRentAmount());
        }

        return updateResult;
    }

    @Override
    @Transactional
    public boolean releaseBooth(Long boothId) {
        Booth booth = getById(boothId);
        if (booth == null) {
