        }

        order.setStatus(status);
        order.setUpdateTime(LocalDateTime.now());

        // 如果订单已支付，可以在这里触发后续业务逻辑
        if (OrderStatus.PAID.equals(status)) {
            // 更新摊位状态
            boothService.assignBoothToVendor(order.getBoothId(), order.getVendorId(), order.getMarketEventId());
        }

        return updateById(order);
    }

